"""Prepare target-allele-matched project research inputs, without scoring them."""
from common import *
def main():
    path=OLD/'project_sequence_pairs.csv';receipt=json.loads((ROOT/'outputs/sleep_frailty_ai_v2/project_prediction_receipt.json').read_text());assert receipt['input_sha256']==sha(path);rows=list(csv.DictReader(path.open()));assert len(rows)==33;result=[]
    for r in rows:
        assert r['status']=='reference_base_and_exact_target_pair_verified';source=OLD/'reference_contexts'/(r['variant']+'.json');assert sha(source)==r['source_sha256'];d=json.loads(source.read_text());ref=d['dna'].upper();alt=r['alternate_sequence'];assert ref==r['reference_sequence'] and len(ref)==len(alt)==270 and ref[134]==r['genome_reference_allele'] and alt[134]==r['tested_alternate_allele'];assert sum(a!=b for a,b in zip(ref,alt))==1;assert d['start']==int(r['position_hg38'])-1-134 and d['end']==d['start']+270 and d['chrom']=='chr'+r['chromosome']
        key=f"chr{r['chromosome']}:{r['position_hg38']}:{r['genome_reference_allele']}:{r['tested_alternate_allele']}"
        for study in STUDIES:result.append({'id':r['variant']+'__'+study,'rsid':r['variant'],'ref_sequence':ref,'alt_sequence':alt,'chromosome':r['chromosome'],'position_hg38':int(r['position_hg38']),'variant_GRCh38':key,'genomic_strand':'+','assay_context':study,'reference_source_url':r['source_url'],'reference_source_sha256':r['source_sha256']})
    target=OUT/'project_raw_inputs.json';target.write_text(json.dumps(result,indent=2)+'\n');(OUT/'project_input_receipt.json').write_text(json.dumps({'variants':33,'rows_two_study_contexts':len(result),'input_sha256':sha(path),'output_sha256':sha(target),'UCSC_cached_source_payloads_verified':33,'allele_convention':'Genome-reference to specified other allele, not a discovery-study risk/effect orientation','genome_build':'GRCh38; each270bp reference center and exact alternate allele checked against the original target pair','clinical_or_disease_accuracy_known':False,'scope':'Preparing molecular research hypotheses. No assay outcomes, phenotypes, risk directions or causal genes assigned.'},indent=2)+'\n');print('Prepared33verified project DNA pairs in2study contexts',flush=True)
if __name__=='__main__':main()
